// The club logo, embedded so it needs no separate image file.
export default function Logo({ size = 40 }: { size?: number }) {
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src="data:image/png;base64,"
      alt="Perth Rifle Metallic Silhouette Club logo"
      width={size}
      height={size}
      style={{ display: "block" }}
    />
  );
}
